mapper.select:
SELECT s.id, s.serial_no, s.material_id, m.code AS material_code, m.name AS material_name, s.warehouse_id, w.code AS warehouse_code, w.name AS warehouse_name, s.batch_no, s.status, s.source_no, s.out_no, s.remark, s.create_time, s.update_time FROM inv_serial s LEFT JOIN base_material m ON m.id = s.material_id LEFT JOIN base_warehouse w ON w.id = s.warehouse_id WHERE s.deleted = 0
AND (s.serial_no = #{q.serialNo} OR s.serial_no LIKE CONCAT(#{q.serialNo}, '%'))
AND s.material_id = #{q.materialId}
AND s.status = #{q.status}
AND (s.source_no LIKE CONCAT('%', #{q.docNo}, '%') OR s.out_no LIKE CONCAT('%', #{q.docNo}, '%'))
ORDER BY s.id DESC
